    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, 'What is the most common etiology of acute laryngitis in an adult?', '["Bacterial infection (Streptococcus)", "Viral infection (e.g., Rhinovirus, Adenovirus)", "Fungal infection", "Autoimmune inflammation", "Allergic reaction"]'::jsonb, 1, 'Acute laryngitis is overwhelmingly caused by common viral upper respiratory tract infections. Bacterial causes are rare.'),
    (v_topic_id, 'A 32-year-old teacher presents with severe hoarseness during a viral URI. What is the most critical recommendation to prevent permanent vocal fold injury?', '["Whisper constantly", "Oral antibiotics", "Strict voice rest and hydration", "Inhaled corticosteroids", "Throat clearing exercises"]'::jsonb, 2, 'Strict voice rest is crucial. Continuing to use inflamed, edematous vocal folds increases the risk of microvascular rupture (hemorrhage) or the development of vocal fold nodules or polyps.'),
    (v_topic_id, 'Why is whispering strongly discouraged during an episode of acute laryngitis?', '["It dries out the throat", "It causes paradoxical vocal cord motion", "It requires excessive muscle tension and places more strain on the vocal folds than normal phonation", "It spreads the virus", "It prevents coughing"]'::jsonb, 2, 'Whispering is an unnatural, strained form of phonation that forces the anterior vocal folds together tightly while leaving the posterior glottis open, causing more mechanical trauma than normal speaking.'),
    (v_topic_id, 'A 2-year-old boy presents with a harsh, barking cough and inspiratory stridor that started at night. He has a low-grade fever and a runny nose. What is the most likely diagnosis?', '["Epiglottitis", "Bacterial tracheitis", "Croup (Laryngotracheobronchitis)", "Asthma", "Foreign body aspiration"]'::jsonb, 2, 'A barking ("seal-like") cough with inspiratory stridor in a toddler following a viral prodrome is the classic presentation of Croup.'),
    (v_topic_id, 'What is the most common viral pathogen responsible for Croup?', '["Respiratory Syncytial Virus (RSV)", "Parainfluenza virus (types 1 and 2)", "Influenza A", "Rhinovirus", "Adenovirus"]'::jsonb, 1, 'Parainfluenza virus is the classic and most common cause of croup, causing subglottic edema.'),
    (v_topic_id, 'An AP neck X-ray in a child with Croup classically demonstrates which radiologic sign?', '["Thumbprint sign", "Steeple sign", "Omega sign", "Sail sign", "String sign"]'::jsonb, 1, 'The "steeple sign" on an AP neck X-ray represents symmetric, tapered narrowing of the subglottic airway caused by mucosal edema.'),
    (v_topic_id, 'What is the standard medical management for a child presenting to the ED with moderate croup and stridor at rest?', '["Oral Amoxicillin", "Nebulized albuterol", "A single dose of Dexamethasone (PO/IM) and nebulized racemic epinephrine", "Immediate intubation", "Tracheostomy"]'::jsonb, 2, 'Steroids (dexamethasone) reduce inflammation over hours, while nebulized racemic epinephrine provides rapid, temporary relief of mucosal edema via alpha-adrenergic vasoconstriction.'),
    (v_topic_id, 'A 45-year-old male presents with severe sore throat, odynophagia, drooling, and a muffled "hot potato" voice. He is sitting leaning forward and appears toxic. He has no cough. What is the most likely diagnosis?', '["Peritonsillar abscess", "Adult epiglottitis (supraglottitis)", "Croup", "Acute viral laryngitis", "Ludwig''s angina"]'::jsonb, 1, 'Rapid onset of severe sore throat, drooling (due to inability to swallow), muffled voice, and a toxic appearance without a cough strongly suggests epiglottitis (supraglottitis).'),
    (v_topic_id, 'In a patient with suspected acute epiglottitis, which of the following actions is absolutely CONTRAINDICATED in the emergency department?', '["Administering IV antibiotics", "Providing supplemental oxygen", "Examining the throat with a tongue depressor", "Obtaining a lateral neck X-ray", "Consulting anesthesia/ENT"]'::jsonb, 2, 'Instrumenting or examining the throat of a patient with epiglottitis can trigger sudden, fatal laryngospasm and complete airway obstruction. The airway must be secured in a controlled setting (OR) before examination.'),
    (v_topic_id, 'Which radiologic sign on a lateral neck X-ray is pathognomonic for epiglottitis?', '["Steeple sign", "Thumbprint sign", "Water bottle sign", "Apple core sign", "Silhouette sign"]'::jsonb, 1, 'The "thumbprint sign" on a lateral neck radiograph represents the massively swollen, edematous epiglottis protruding into the airway.'),
    (v_topic_id, 'Historically, before widespread vaccination, what was the most common bacterial cause of pediatric epiglottitis?', '["Streptococcus pneumoniae", "Staphylococcus aureus", "Haemophilus influenzae type b (Hib)", "Neisseria meningitidis", "Corynebacterium diphtheriae"]'::jsonb, 2, 'Haemophilus influenzae type b (Hib) was the overwhelming cause. The Hib vaccine has made pediatric epiglottitis rare, shifting the demographic primarily to adults (often caused by Strep or Staph).'),
    (v_topic_id, 'A 5-year-old child recovering from viral croup suddenly develops a high fever, severe stridor, and a toxic appearance. Endoscopy reveals thick, purulent secretions and crusts in the trachea. What is the diagnosis?', '["Epiglottitis", "Bacterial tracheitis", "Severe asthma", "Foreign body aspiration", "Pneumonia"]'::jsonb, 1, 'Bacterial tracheitis is a severe, life-threatening secondary bacterial infection (often Staph aureus) that complicates viral croup. It presents as "croup that gets suddenly worse" and does not respond to epinephrine.'),
    (v_topic_id, 'What is the most immediate life-threatening complication of Bacterial Tracheitis?', '["Sepsis", "Airway obstruction due to sloughing of thick, purulent pseudomembranes (crusts)", "Meningitis", "Vocal cord paralysis", "Esophageal perforation"]'::jsonb, 1, 'The thick, purulent crusts can peel off the tracheal wall and completely plug the airway, often requiring intubation and frequent bronchoscopic suctioning.'),
    (v_topic_id, 'A 50-year-old homeless male with a history of incarceration presents with a chronic cough, night sweats, weight loss, and severe hoarseness with painful swallowing. Laryngoscopy shows a granular, ulcerated mass on the posterior glottis. What is the most likely diagnosis?', '["Squamous cell carcinoma", "Laryngeal tuberculosis", "Croup", "Laryngopharyngeal reflux", "Vocal fold nodule"]'::jsonb, 1, 'Laryngeal TB mimics carcinoma but occurs in the setting of pulmonary TB. It classically affects the posterior larynx where infected sputum pools.'),
    (v_topic_id, 'Laryngeal tuberculosis is almost exclusively secondary to active infection in which other organ?', '["Kidneys", "Brain", "Lungs (cavitary pulmonary TB)", "Bones (Pott''s disease)", "Liver"]'::jsonb, 2, 'Laryngeal TB is caused by the direct seeding of the laryngeal mucosa by Mycobacterium tuberculosis-laden sputum coughed up from active cavitary lung lesions.'),
    (v_topic_id, 'What is the recommended initial management for a patient diagnosed with laryngeal tuberculosis?', '["Total laryngectomy", "Standard multi-drug anti-tuberculous chemotherapy (RIPE therapy) and strict respiratory isolation", "Radiation therapy", "Corticosteroids", "Surgical excision of the granulomas"]'::jsonb, 1, 'Laryngeal TB is highly infectious because coughing aerosolizes the bacilli directly from the upper airway. It is treated medically with standard TB protocols.'),
    (v_topic_id, 'A 60-year-old asthmatic patient complains of a 3-week history of mild hoarseness. He uses a high-dose inhaled corticosteroid daily. Laryngoscopy reveals thin, white "cottage cheese" plaques on the vocal folds. What is the diagnosis?', '["Leukoplakia", "Squamous cell carcinoma", "Laryngeal candidiasis", "Laryngeal diphtheria", "Vocal fold keratosis"]'::jsonb, 2, 'Laryngeal candidiasis (thrush) is common in patients using steroid inhalers without proper oral rinsing. It presents with wipeable white plaques.'),
    (v_topic_id, 'What is the appropriate treatment for laryngeal candidiasis caused by inhaler use?', '["Surgical stripping of the vocal cords", "Oral antifungal therapy (e.g., Fluconazole) and patient education on inhaler hygiene (rinsing mouth)", "Antibiotics", "Total voice rest", "Radiation"]'::jsonb, 1, 'Medical therapy resolves the fungal infection, but educating the patient to use a spacer and rinse/spit after inhaler use is necessary to prevent recurrence.'),
    (v_topic_id, 'A non-immunized child presents with a low-grade fever, sore throat, and a thick, tough, grayish pseudomembrane covering the tonsils, pharynx, and extending into the larynx, causing stridor. What is the diagnosis?', '["Croup", "Laryngeal Diphtheria", "Epiglottitis", "Candidiasis", "Bacterial tracheitis"]'::jsonb, 1, 'Corynebacterium diphtheriae causes a classic, tough, bleeding pseudomembrane. The exotoxin can cause severe systemic effects (myocarditis, neuropathy) and airway obstruction.'),
    (v_topic_id, 'If the pseudomembrane of Diphtheria is forcefully scraped or removed, what typically happens?', '["It reveals healthy mucosa underneath", "It bleeds profusely", "The patient instantly recovers", "It turns into a cyst", "Nothing"]'::jsonb, 1, 'The diphtheritic pseudomembrane is tightly adherent to the underlying tissues; attempts to scrape it off result in significant bleeding.'),
    (v_topic_id, 'What is the primary treatment for respiratory diphtheria?', '["Diphtheria antitoxin and antibiotics (Penicillin or Erythromycin)", "Surgical excision of the membrane", "Antifungals", "Steroids alone", "Observation"]'::jsonb, 0, 'Immediate administration of the antitoxin is critical to neutralize circulating exotoxin, while antibiotics eradicate the organism to stop further toxin production.'),
    (v_topic_id, 'A 55-year-old male presents with a 6-month history of frequent throat clearing, a sensation of a lump in his throat (globus), and a rough voice that is worse in the morning. He denies typical heartburn. What is the most likely diagnosis?', '["Laryngopharyngeal Reflux (LPR)", "Vocal fold polyp", "Allergic rhinitis", "Achalasia", "Thyroid cancer"]'::jsonb, 0, 'LPR often presents with "silent reflux" symptoms (hoarseness, globus, chronic cough, throat clearing) without classic GERD symptoms like heartburn or regurgitation.'),
    (v_topic_id, 'What is the classic laryngoscopic finding in a patient with Laryngopharyngeal Reflux (LPR)?', '["Anterior glottic web", "Bilateral vocal fold paralysis", "Erythema, edema, and pachydermia of the posterior larynx (arytenoids and interarytenoid area)", "A single large polyp on the vocal fold", "White leukoplakia plaques"]'::jsonb, 2, 'Because the refluxate spills over the postcricoid region, the posterior larynx (arytenoids and interarytenoid space) bears the brunt of the acid/pepsin damage, resulting in posterior glottic erythema and "cobblestoning" (pachydermia).'),
    (v_topic_id, 'Which enzyme found in gastric juice is believed to cause significant damage to the laryngeal mucosa in LPR, even in weakly acidic environments?', '["Amylase", "Lipase", "Pepsin", "Trypsin", "Lactase"]'::jsonb, 2, 'Pepsin from the stomach can bind to laryngeal epithelium and be reactivated by subsequent weak acid reflux events or even dietary acids, causing ongoing tissue damage.'),
    (v_topic_id, 'What is the recommended first-line medical therapy for suspected Laryngopharyngeal Reflux (LPR)?', '["Antacids PRN", "Proton Pump Inhibitors (PPIs) given twice daily for a minimum of 3-6 months, along with diet/lifestyle changes", "H2 blockers once daily", "Fundoplication surgery immediately", "Voice therapy alone"]'::jsonb, 1, 'LPR is notoriously harder to treat than classic GERD. It requires twice-daily, high-dose PPI therapy for a prolonged period (3-6 months) because the laryngeal mucosa lacks the protective mechanisms of the esophagus and takes longer to heal.'),
    (v_topic_id, 'Which lifestyle modification is critical for the management of LPR?', '["Drinking more coffee", "Eating large meals right before bedtime", "Elevating the head of the bed and avoiding eating within 3 hours of sleep", "Sleeping completely flat", "Consuming alcohol before bed"]'::jsonb, 2, 'Preventing nighttime reflux events by keeping the stomach empty before lying down and utilizing gravity is crucial for healing the posterior larynx.'),
    (v_topic_id, 'A patient with LPR fails to improve after 6 months of strict twice-daily PPI therapy and lifestyle modifications. What diagnostic test is indicated next?', '["Barium swallow", "24-hour dual-probe (pharyngeal and esophageal) pH monitoring with impedance testing", "CT scan of the neck", "MRI of the brain", "Direct laryngoscopy in the OR"]'::jsonb, 1, 'If empiric therapy fails, objective confirmation of reflux reaching the pharynx is required. A dual-probe pH/impedance study measures acid and non-acid reflux events at both the distal esophagus and the upper esophageal sphincter.'),
    (v_topic_id, 'What is a severe, chronic complication of untreated LPR affecting the posterior glottis?', '["Vocal fold cysts", "Reinke''s edema", "Contact ulcers and intubation/contact granulomas of the vocal processes", "Anterior glottic web", "Laryngeal papillomatosis"]'::jsonb, 2, 'Chronic acid irritation to the thin mucosa over the arytenoid cartilages can lead to ulceration and the formation of contact granulomas.'),
    (v_topic_id, 'Laryngeal Syphilis in its tertiary stage can present with which destructive lesion?', '["A simple polyp", "A gumma that can cause extensive cartilage destruction and severe scarring", "A vocal fold nodule", "Reinke''s edema", "A subglottic hemangioma"]'::jsonb, 1, 'Tertiary syphilis can cause gummas in the larynx, leading to painless, progressive destruction of the laryngeal cartilages and severe, permanent fibrotic stenosis.'),
    (v_topic_id, 'Which clinical feature distinguishes laryngeal syphilis from laryngeal tuberculosis or carcinoma?', '["It is excruciatingly painful", "It is typically painless despite massive ulceration and destruction", "It only affects children", "It always causes complete aphonia", "It responds to Botox"]'::jsonb, 1, 'Unlike TB (which is very painful) or advanced SCC, syphilitic gummas of the larynx are notoriously painless despite causing significant tissue destruction.'),
    (v_topic_id, 'What is the treatment of choice for laryngeal syphilis?', '["Radiation therapy", "Penicillin", "Total laryngectomy", "Fluconazole", "Acyclovir"]'::jsonb, 1, 'As with all stages of syphilis, Penicillin remains the definitive treatment, though it cannot reverse established cartilaginous destruction or scarring.'),
    (v_topic_id, 'Which autoimmune condition can cause chronic inflammation, fixation, and ultimately ankylosis of the cricoarytenoid joint, mimicking vocal fold paralysis?', '["Lupus", "Rheumatoid Arthritis (RA)", "Multiple Sclerosis", "Myasthenia Gravis", "Sjogren''s Syndrome"]'::jsonb, 1, 'The cricoarytenoid joint is a true synovial joint. Rheumatoid arthritis can cause acute arthritis (pain, hoarseness) and eventual fusion (ankylosis) of the joint, fixing the vocal fold in place.'),
    (v_topic_id, 'How can a physician distinguish between true vocal fold paralysis and cricoarytenoid joint ankylosis (e.g., from RA) in a patient with an immobile vocal cord?', '["CT scan of the neck", "Laryngeal electromyography (LEMG) or direct palpation of the arytenoid under general anesthesia", "Blood test for rheumatoid factor", "Trial of Botox", "MRI of the brain"]'::jsonb, 1, 'LEMG will show normal electrical activity in ankylosis but denervation in paralysis. In the OR, the arytenoid will be rigid to palpation in ankylosis, but freely mobile in paralysis.'),
    (v_topic_id, 'A patient with Relapsing Polychondritis presents with stridor and dyspnea. What laryngeal/tracheal structure is under autoimmune attack?', '["The mucosa", "The vocal fold epithelium", "The cartilaginous rings of the trachea and the laryngeal cartilages", "The recurrent laryngeal nerve", "The vocalis muscle"]'::jsonb, 2, 'Relapsing polychondritis is an autoimmune disease targeting cartilage (ears, nose, airway). Destruction of the laryngeal and tracheal cartilages leads to progressive, life-threatening airway collapse (tracheobronchomalacia).'),
    (v_topic_id, 'What is the primary medical treatment for acute airway flares in Relapsing Polychondritis?', '["High-dose systemic corticosteroids and immunosuppressants", "Penicillin", "Antacids", "Botox injections", "Antihistamines"]'::jsonb, 0, 'Aggressive immunosuppression is required to halt the cartilaginous destruction, though advanced cases often require airway stenting or tracheostomy.'),
    (v_topic_id, 'Wegener''s Granulomatosis (Granulomatosis with Polyangiitis) classically affects the upper airway by causing which specific complication?', '["Vocal fold nodules", "Subglottic stenosis", "Bilateral vocal fold paralysis", "Reinke''s edema", "Laryngocele"]'::jsonb, 1, 'GPA frequently causes necrotizing granulomatous inflammation in the subglottis, leading to severe, recurrent subglottic stenosis.'),
    (v_topic_id, 'A 35-year-old female presents with idiopathic subglottic stenosis (iSGS). Which laboratory test should be checked to rule out a systemic autoimmune cause before diagnosing it as "idiopathic"?', '["Rheumatoid Factor", "c-ANCA (Anti-neutrophil cytoplasmic antibodies)", "ANA", "Anti-dsDNA", "TSH"]'::jsonb, 1, 'c-ANCA is highly specific for Granulomatosis with Polyangiitis (Wegener''s), which must be ruled out because GPA requires systemic immunosuppression, whereas true iSGS is treated locally.'),
    (v_topic_id, 'Which of the following is a classic demographic for Idiopathic Subglottic Stenosis (iSGS)?', '["Elderly males with a smoking history", "Adult females, typically Caucasian, between 30 and 50 years old", "Infants", "Teenage males", "Patients with a history of prolonged intubation"]'::jsonb, 1, 'Idiopathic subglottic stenosis almost exclusively affects adult Caucasian females. The exact cause is unknown, but hormonal factors and aberrant wound healing are suspected.'),
    (v_topic_id, 'Patients with Idiopathic Subglottic Stenosis are frequently misdiagnosed for years with which common pulmonary condition?', '["COPD", "Asthma", "Pneumonia", "Cystic Fibrosis", "Pulmonary embolism"]'::jsonb, 1, 'Because they present with progressive dyspnea on exertion and transmitted stridor that sounds like wheezing, they are often mistakenly treated with asthma inhalers for years without relief.'),
    (v_topic_id, 'What does the flow-volume loop on spirometry classically show in a patient with severe subglottic stenosis?', '["A restrictive pattern", "Flattening of both the inspiratory and expiratory limbs (a fixed upper airway obstruction)", "Flattening of the expiratory limb only", "Flattening of the inspiratory limb only", "A completely normal loop"]'::jsonb, 1, 'Subglottic stenosis creates a fixed, rigid narrowing of the airway. This restricts airflow equally during both inspiration and expiration, truncating both loops on spirometry.'),
    (v_topic_id, 'A patient with Idiopathic Subglottic Stenosis undergoes a bronchoscopic intervention. What does this typically involve?', '["Placement of a permanent metal stent", "Radial incisions with a laser followed by balloon dilation and local steroid injection", "Complete removal of the cricoid cartilage", "Injection of Botox", "Tracheostomy only"]'::jsonb, 1, 'Endoscopic dilation with local corticosteroid injection is the standard minimally invasive management for iSGS to stretch the scar and delay recurrence.'),
    (v_topic_id, 'A patient presents with acute angioedema of the larynx and lips after starting a new medication for hypertension. Which class of medication is most likely responsible?', '["Beta-blockers", "Calcium channel blockers", "ACE inhibitors", "Diuretics", "Alpha-blockers"]'::jsonb, 2, 'ACE inhibitors can cause bradykinin-mediated angioedema. This can be life-threatening if it involves the tongue, pharynx, or larynx, leading to rapid airway obstruction.'),
    (v_topic_id, 'How does the treatment for ACE-inhibitor-induced laryngeal angioedema differ from allergic (histamine-mediated) anaphylaxis?', '["It responds faster to epinephrine", "It does NOT reliably respond to epinephrine, antihistamines, or steroids; airway observation and prompt intubation if worsening are critical", "It requires antibiotics", "It is treated with antifungal agents", "It requires emergency tracheostomy immediately"]'::jsonb, 1, 'Because it is bradykinin-mediated, standard anaphylaxis treatments are ineffective. Management is supportive airway care, stopping the drug, and potentially using specific agents like icatibant or fresh frozen plasma in severe cases.'),
    (v_topic_id, 'Which hereditary condition causes recurrent episodes of severe, spontaneous laryngeal angioedema without hives or pruritus?', '["Cystic Fibrosis", "Hereditary Angioedema (HAE) due to C1-esterase inhibitor deficiency", "Sickle cell anemia", "Hemophilia A", "Alpha-1 antitrypsin deficiency"]'::jsonb, 1, 'HAE is an autosomal dominant condition causing uninhibited complement and bradykinin activation. Minor trauma or stress can trigger massive, life-threatening airway swelling.'),
    (v_topic_id, 'What is the specific acute medical therapy for a laryngeal attack in a patient with known Hereditary Angioedema (C1-INH deficiency)?', '["High-dose Epinephrine", "Intravenous C1-inhibitor concentrate or a bradykinin receptor antagonist (e.g., Icatibant)", "Oral steroids", "Albuterol", "Antihistamines"]'::jsonb, 1, 'Replacing the missing enzyme (C1-INH) or blocking the bradykinin pathway directly stops the attack. Epinephrine and steroids are ineffective.'),
    (v_topic_id, 'Sarcoidosis can affect the larynx. Which part of the larynx is most characteristically involved in laryngeal sarcoidosis?', '["The true vocal folds", "The epiglottis, presenting as a pale, thickened, turban-like or ''omega-shaped'' swelling", "The subglottis", "The vocal processes", "The laryngeal ventricle"]'::jsonb, 1, 'Laryngeal sarcoid classically infiltrates the epiglottis and supraglottic structures with non-caseating granulomas, creating a pale, massively thickened epiglottis that can obstruct the airway.'),
    (v_topic_id, 'What is the typical presentation of Laryngeal Amyloidosis?', '["Severe pain and bleeding", "A smooth, firm, yellowish-orange submucosal mass (often in the false vocal folds or subglottis) causing hoarseness or stridor", "A rapidly growing, ulcerated, fungating mass", "Thin, white, wipeable plaques", "A fluid-filled cyst"]'::jsonb, 1, 'Amyloidosis in the larynx is usually localized (not systemic). It deposits extracellular protein, forming smooth, firm masses that slowly compromise voice or airway.'),
    (v_topic_id, 'Which special histological stain is used to confirm the diagnosis of laryngeal amyloidosis on biopsy?', '["Periodic acid-Schiff (PAS)", "Congo red stain showing apple-green birefringence under polarized light", "GMS (Grocott''s methenamine silver)", "Ziehl-Neelsen (Acid-fast)", "H&E only"]'::jsonb, 1, 'The Congo red stain with characteristic apple-green birefringence is the gold standard for diagnosing amyloid deposits in tissue.'),
    (v_topic_id, 'A patient presents with acute, excruciating throat pain, fever, and a rapidly enlarging, unilateral swelling of the neck. CT shows a fluid collection with a rim-enhancing wall lateral to the larynx. What is the diagnosis?', '["Epiglottitis", "Parapharyngeal or retropharyngeal space abscess", "Croup", "Laryngocele", "Thyroid cyst"]'::jsonb, 1, 'Deep neck space infections (abscesses) can rapidly compromise the airway by pushing the pharyngeal or laryngeal walls inward. They require IV antibiotics and often surgical drainage.'),
    (v_topic_id, 'Which finding on flexible laryngoscopy is most concerning for impending airway loss in a patient with a deep neck space infection?', '["Mild erythema of the vocal cords", "Edema of the epiglottis and aryepiglottic folds, with deviation of the larynx to the contralateral side", "A vocal cord nodule", "A normal airway", "Pachydermia"]'::jsonb, 1, 'Mass effect pushing the larynx, combined with reactive supraglottic edema, indicates severe airway compromise requiring immediate securing of the airway (often awake fiberoptic intubation).');
