-- ENT Laryngeal Disorders & Hoarseness MCQs (Part 2/6)
-- Target platform: Supabase (Postgres)
-- Topic Slug: ent-laryngeal

BEGIN;

DO $$
DECLARE
    v_topic_id UUID;
BEGIN
    SELECT id INTO v_topic_id FROM topics WHERE slug = 'ent-laryngeal' LIMIT 1;
    IF v_topic_id IS NULL THEN
        RAISE EXCEPTION 'Topic slug ent-laryngeal not found.';
    END IF;


END $$;
COMMIT;
